// ==================== API Key 管理接口 ====================

// ListAPIKeys 获取当前用户的 API Key 列表
// @router /user/api-keys [GET]
func ListAPIKeys(ctx context.Context, c *app.RequestContext) {
	// 从上下文获取用户ID
	userIDVal, exists := c.Get("user_id")
	if !exists {
		c.JSON(consts.StatusUnauthorized, map[string]interface{}{
			"code":    errcode.CodeUnauthorized,
			"message": "用户未登录",
		})
		return
	}

	userID, ok := userIDVal.(uint)
	if !ok {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "用户ID类型错误",
		})
		return
	}

	keys, err := getUserService().ListAPIKeys(ctx, userID)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "获取 API Key 失败: " + err.Error(),
		})
		return
	}

	// 转换为响应格式
	respKeys := make([]map[string]interface{}, len(keys))
	for i, key := range keys {
		respKeys[i] = map[string]interface{}{
			"id":           key.ID,
			"name":         key.Name,
			"prefix":       key.Prefix,
			"last_used_at": formatTime(key.LastUsedAt),
			"last_used_ip": key.LastUsedIP,
			"expires_at":   formatTime(key.ExpiresAt),
			"created_at":   formatTime(key.CreatedAt),
			"revoked":      key.Revoked,
		}
	}

	c.JSON(consts.StatusOK, map[string]interface{}{
		"code":    200,
		"message": "获取成功",
		"keys":    respKeys,
	})
}

// CreateAPIKey 为当前用户创建新的 API Key
// @router /user/api-keys [POST]
func CreateAPIKey(ctx context.Context, c *app.RequestContext) {
	// 从上下文获取用户ID
	userIDVal, exists := c.Get("user_id")
	if !exists {
		c.JSON(consts.StatusUnauthorized, map[string]interface{}{
			"code":    errcode.CodeUnauthorized,
			"message": "用户未登录",
		})
		return
	}

	userID, ok := userIDVal.(uint)
	if !ok {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "用户ID类型错误",
		})
		return
	}

	// 解析请求体
	var req struct {
		Name          string `json:"name"`
		ExpiresAt     string `json:"expires_at"`
		ExpiresInDays *int64 `json:"expires_in_days"`
	}
	if err := c.Bind(&req); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "请求参数错误: " + err.Error(),
		})
		return
	}

	// 处理过期时间
	var expiresAt *time.Time
	var expiresInDays *int64

	if req.ExpiresAt != "" {
		t, err := time.Parse(time.RFC3339, strings.TrimSpace(req.ExpiresAt))
		if err != nil {
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    400,
				"message": "expires_at 必须为 RFC3339 格式",
			})
			return
		}
		expiresAt = &t
	}

	if req.ExpiresInDays != nil && *req.ExpiresInDays > 0 {
		expiresInDays = req.ExpiresInDays
	}

	// 调用 service 创建 API Key
	result, err := getUserService().CreateAPIKey(ctx, uint(userID), &userservice.CreateAPIKeyReq{
		Name:          req.Name,
		ExpiresAt:     expiresAt,
		ExpiresInDays: expiresInDays,
	})
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": err.Error(),
		})
		return
	}

	// 转换为响应格式
	c.JSON(consts.StatusOK, map[string]interface{}{
		"code":    200,
		"message": "API Key 生成成功",
		"data": map[string]interface{}{
			"key": result.Key,
			"api_key": map[string]interface{}{
				"id":           result.APIKey.ID,
				"name":         result.APIKey.Name,
				"prefix":       result.APIKey.Prefix,
				"last_used_at": formatTime(result.APIKey.LastUsedAt),
				"expires_at":   formatTime(result.APIKey.ExpiresAt),
				"created_at":   formatTime(result.APIKey.CreatedAt),
				"revoked":      result.APIKey.Revoked,
			},
		},
	})
}

// DeleteAPIKey 撤销指定的 API Key
// @router /user/api-keys/:id [DELETE]
func DeleteAPIKey(ctx context.Context, c *app.RequestContext) {
	// 从上下文获取用户ID
	userIDVal, exists := c.Get("user_id")
	if !exists {
		c.JSON(consts.StatusUnauthorized, map[string]interface{}{
			"code":    errcode.CodeUnauthorized,
			"message": "用户未登录",
		})
		return
	}

	userID, ok := userIDVal.(uint)
	if !ok {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "用户ID类型错误",
		})
		return
	}

	// 获取路径参数中的 key ID
	keyIDStr := c.Param("id")
	if keyIDStr == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "密钥ID不能为空",
		})
		return
	}

	keyID, err := strconv.ParseUint(keyIDStr, 10, 64)
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "密钥ID格式错误",
		})
		return
	}

	// 调用 service 撤销 API Key
	if err := getUserService().DeleteAPIKey(ctx, uint(userID), uint(keyID)); err != nil {
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    404,
			"message": err.Error(),
		})
		return
	}

	c.JSON(consts.StatusOK, map[string]interface{}{
		"code":    200,
		"message": "API Key 已撤销",
	})
}

// formatTime 格式化时间指针为字符串
func formatTime(t *time.Time) string {
	if t == nil {
		return ""
	}
	return t.Format("2006-01-02 15:04:05")
}

// RevokeAllAPIKeys 一键吊销当前用户全部有效 API Key（JWT-only，应急止损）
